<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){try{$kind=$_POST['kind']??'';if($kind==='year'){$name=trim($_POST['school_year_name']??'');$start=$_POST['start_date']?:null;$end=$_POST['end_date']?:null;$conn->begin_transaction();if(isset($_POST['active']))$conn->query('UPDATE school_years SET is_active=0');$active=isset($_POST['active'])?1:0;$q=$conn->prepare('INSERT INTO school_years(school_year_name,start_date,end_date,is_active) VALUES(?,?,?,?)');$q->bind_param('sssi',$name,$start,$end,$active);$q->execute();$conn->commit();}elseif($kind==='activate-year'){$id=(int)$_POST['id'];$conn->begin_transaction();$conn->query('UPDATE school_years SET is_active=0');$q=$conn->prepare('UPDATE school_years SET is_active=1 WHERE school_year_id=?');$q->bind_param('i',$id);$q->execute();$conn->commit();}elseif($kind==='strand'){$code=trim($_POST['strand_code']);$name=trim($_POST['strand_name']);$q=$conn->prepare('INSERT INTO strands(strand_code,strand_name) VALUES(?,?)');$q->bind_param('ss',$code,$name);$q->execute();}elseif($kind==='section'){$year=(int)$_POST['school_year_id'];$grade=$_POST['grade_level'];$strand=(int)$_POST['strand_id'];$name=trim($_POST['section_name']);$q=$conn->prepare('INSERT INTO sections(school_year_id,grade_level,strand_id,section_name) VALUES(?,?,?,?)');$q->bind_param('isis',$year,$grade,$strand,$name);$q->execute();}elseif($kind==='subject'){$code=trim($_POST['subject_code']);$name=trim($_POST['subject_name']);$grade=$_POST['grade_level'];$strand=($_POST['strand_id']??'')===''?null:(int)$_POST['strand_id'];$q=$conn->prepare('INSERT INTO subjects(subject_code,subject_name,grade_level,strand_id) VALUES(?,?,?,?)');$q->bind_param('sssi',$code,$name,$grade,$strand);$q->execute();}elseif($kind==='period'){$year=(int)$_POST['school_year_id'];$name=trim($_POST['period_name']);$order=(int)$_POST['period_order'];$q=$conn->prepare('INSERT INTO grading_periods(school_year_id,period_name,period_order) VALUES(?,?,?)');$q->bind_param('isi',$year,$name,$order);$q->execute();}audit($conn,$_SESSION['user_id'],'academic_setup_'.$kind,'academic_setup');flash('Academic setup saved.');}catch(Throwable $e){if($conn->errno)$conn->rollback();flash('Could not save. Check required values and duplicate codes/names.','error');}go('/spi/admin/academic-setup.php');}
$years=$conn->query('SELECT * FROM school_years ORDER BY school_year_id DESC');$strands=$conn->query('SELECT * FROM strands WHERE status="active" ORDER BY strand_name');page_start('Academic setup');echo '<h1>Academic setup</h1><p>Enter only school-approved years, strands/tracks, sections, subjects, and grading periods.</p><div class="grid"><section class="card"><h2>School year</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="year"><label>Name<input name="school_year_name" placeholder="2026-2027" required></label><label>Start date<input type="date" name="start_date"></label><label>End date<input type="date" name="end_date"></label><label><input type="checkbox" name="active" value="1"> Set active</label><button>Create school year</button></form></section><section class="card"><h2>Strand / track</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="strand"><label>Code<input name="strand_code" required></label><label>Name<input name="strand_name" required></label><button>Add strand</button></form></section><section class="card"><h2>Section</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="section"><label>School year<select name="school_year_id">';foreach($years as $y)echo '<option value="'.(int)$y['school_year_id'].'">'.e($y['school_year_name']).'</option>';echo '</select></label><label>Grade<select name="grade_level"><option value="11">Grade 11</option><option value="12">Grade 12</option></select></label><label>Strand / track<select name="strand_id">';foreach($strands as $s)echo '<option value="'.(int)$s['strand_id'].'">'.e($s['strand_code'].' — '.$s['strand_name']).'</option>';echo '</select></label><label>Section name<input name="section_name" required></label><button>Add section</button></form></section><section class="card"><h2>Subject</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="subject"><label>Code<input name="subject_code" required></label><label>Name<input name="subject_name" required></label><label>Grade<select name="grade_level"><option value="11">Grade 11</option><option value="12">Grade 12</option></select></label><label>Strand / track (optional)<select name="strand_id"><option value="">Core subjects</option>';foreach($strands as $s)echo '<option value="'.(int)$s['strand_id'].'">'.e($s['strand_code']).'</option>';echo '</select></label><button>Add subject</button></form></section><section class="card"><h2>Grading period</h2><form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="period"><label>School year<select name="school_year_id">';foreach($years as $y)echo '<option value="'.(int)$y['school_year_id'].'">'.e($y['school_year_name']).'</option>';echo '</select></label><label>Period name<input name="period_name" placeholder="School-approved period label" required></label><label>Order<input type="number" name="period_order" min="1" required></label><button>Add period</button></form></section></div><h2>Years and activation</h2><div class="tablewrap"><table><tr><th>Year</th><th>Dates</th><th>Active</th><th>Action</th></tr>';foreach($years as $y){echo '<tr><td>'.e($y['school_year_name']).'</td><td>'.e($y['start_date']).' – '.e($y['end_date']).'</td><td>'.($y['is_active']?'Yes':'No').'</td><td>';if(!$y['is_active'])echo '<form method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="kind" value="activate-year"><input type="hidden" name="id" value="'.(int)$y['school_year_id'].'"><button>Set active</button></form>';echo '</td></tr>';}echo '</table></div>';page_end();
